export const getPatchMeSettingsUrl = () => {




  return `/me/settings`
}

/**
 * Updates the current operator's settings
 * @summary Update operator settings
 */
export const patchMeSettings = async (updateSettingsRequest: UpdateSettingsRequest, options?: Parameters<typeof customAxios>[1]): Promise<SettingsResponseResult> => {

    const getHeaders = (h?: HeadersInit | Headers): Record<string, string> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
return customAxios<SettingsResponseResult>(getPatchMeSettingsUrl(),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(updateSettingsRequest)
  }
);}





